#!/usr/bin/env python3
"""Build a local gallery from existing recorded specimens and rendered images.

No pending specimen is listed. Missing viewers fall back to available images.
The page makes no network request except its relative local image assets.
"""
import argparse, json, pathlib, re, struct, zlib
p=argparse.ArgumentParser();p.add_argument('directory',nargs='?',default='outputs');a=p.parse_args();root=pathlib.Path(a.directory)

def ppm_png(source,target):
    raw=source.read_bytes();m=re.match(rb'P6\s+(\d+)\s+(\d+)\s+255\s',raw)
    if not m:return False
    w,h=map(int,m.groups());pixels=raw[m.end():]
    if len(pixels)!=w*h*3:return False
    def chunk(name,body):return struct.pack('>I',len(body))+name+body+struct.pack('>I',zlib.crc32(name+body))
    scan=b''.join(b'\0'+pixels[y*w*3:(y+1)*w*3] for y in range(h))
    target.write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(scan,6))+chunk(b'IEND',b''));return True

names={
'choir':('Choir','A rhythm becomes a memory','Excitable activity consumes soluble feedstock and leaves persistent material. The accumulated deposit changes the medium that carries the next wave.'),
'neural':('Neural interior','Local decisions, shared material','A field controller senses its surroundings and changes the rate of material conversion. Inspect its spatial traces alongside the soluble and active fields.'),
'lace-fine':('Lace','A finer field','A finer grid records excitation and material accumulation in three dimensions. Turn the volume to follow the interfaces through its depth.'),
'neural-metal-smoke':('Metal / smoke','The same state, another light','A second optical treatment of a neural material specimen. Compare how scattering, absorption, and viewpoint reveal its interior.'),
'electrical':('Electrical garden','A pulse follows its history','Conducting channels grow through a field and leave a structure that shapes subsequent growth.'),
'acoustic':('Acoustic instrument','Sound writes its surroundings','An acoustic field and a changing material exchange influence. The recorded interior shows the traces of that interaction.'),
'writing/scaffold':('Written scaffold','A path becomes material','A directed writing process deposits a scaffold. Explore its recorded trace and rendered structure.'),
'writing/living':('Living trace','A scaffold meets a changing medium','A written scaffold interacts with an active material field. Compare this recording with the scaffold specimen.'),
'phase':('Phase separation','Domains take shape','A phase field develops spatial domains. Inspect how their interfaces change during the recording.'),
'mechanics':('Material mechanics','Stress changes an interior','Explore the recorded mechanical fields and the structures that emerge from their interaction.'),
'ecology':('Material ecology','Growth meets a shared resource','Inherited neural rules share a finite resource. The colored points mark surviving lineages on a shallow slide; the population dynamics are two-dimensional.'),
'grin':('Graded optics','An interior bends light','Explore the optical paths through a spatially varying refractive medium.'),
'writing':('Material writing','A travelling trace','A moving process writes into a material field. Its path becomes part of the environment that it encounters next.')}
names['dense-128']=('Dense choir / 128³','A larger recorded field','A complete 3,414-step GPU study with a smooth deposited interior. This photograph observes its intermediate state near t=5; the simulation runs through t=10.')
names['bigruns/dense-128-study']=names['dense-128']
items=[]
directories=list(root.iterdir())+[d for d in [root/'writing'/'scaffold',root/'writing'/'living',root/'bigruns'/'dense-128-study'] if d.is_dir()]
for directory in directories:
    if not directory.is_dir() or directory.name=='scout':continue
    manifest=directory/'run.json'; volume=directory/'volume.json'
    if not volume.exists():volume=directory/'volume'/'volume.json'
    if not manifest.exists() and not volume.exists():continue
    try:run=json.loads(manifest.read_text()) if manifest.exists() else json.loads(volume.read_text())
    except (ValueError,OSError):continue
    images=[]
    preferred=['photograph-1200.png','phase-glass.png','polished-network.png','population-glass.png','polished-inclusion.png','polished-wave.png','polished.png','cycles-pressure.png','cycles-interfaces.png','cycles.png','cycles-fronts.png','cycles-mid.png','cycles-above.png','specimen.png','projection.png','gallery-preview.png']
    candidates=list(directory.glob('*.png'))+list(directory.glob('*.jpg'))+list(directory.glob('*.webp'))
    candidates=[x for x in candidates if not any(word in x.name for word in ['check','screenshot','test'])]
    if not candidates and (directory/'specimen.ppm').exists():
        out=directory/'gallery-preview.png'
        if ppm_png(directory/'specimen.ppm',out):candidates=[out]
    candidates.sort(key=lambda x:(preferred.index(x.name) if x.name in preferred else len(preferred),x.name))
    for image in candidates:
        label='Rendered material' if image.name.startswith(('cycles','polished','phase-glass','population-glass','photograph')) else 'Recorded field projection'
        if 'above' in image.name:label+=' / above'
        elif 'interfaces' in image.name:label+=' / interfaces'
        elif 'fronts' in image.name:label+=' / activity fronts'
        elif 'mid' in image.name:label+=' / intermediate frame'
        images.append(dict(src=image.relative_to(root).as_posix(),caption=label))
    viewer=(directory/'viewer.html').exists()
    if not images and not viewer:continue
    key=directory.relative_to(root).as_posix();category=key if key in names else next((k for k in names if key.startswith(k+'-')),None)
    name,subtitle,description=names.get(category,(run.get('title',key.replace('-',' ').title()),'A material process','Explore the recorded specimen and its rendered views.'))
    frames=run.get('frames',[]);shape=run.get('shape',[]);backend=run.get('backend','')
    if 'budget' in run:
        shape=[run['budget']['resolution']]*3;backend=run['budget']['backend']
    notes=root.parent/'docs'/('bigruns.md' if key in ('dense-128','bigruns/dense-128-study') else (key.split('/')[0])+'.md')
    config_name=next((name for name in ('config.toml','profile.toml') if (directory/name).exists()),None)
    items.append(dict(notes='../docs/'+notes.name if notes.exists() else None,id=key,name=name,subtitle=subtitle,description=description,images=images,viewer=key+'/viewer.html' if viewer else None,manifest=manifest.relative_to(root).as_posix() if manifest.exists() else volume.relative_to(root).as_posix(),config=key+'/'+config_name if config_name else None,frames=len(frames),shape=shape,backend=backend))
order=['choir','lace-fine','neural','electrical','acoustic','writing/scaffold','writing/living','phase','mechanics','ecology','grin','neural-metal-smoke'];items.sort(key=lambda x:(order.index(x['id']) if x['id'] in order else len(order),x['id']))
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>Interior / material studies</title><style>
:root{color-scheme:dark;background:#080d12;color:#d6d8d2;font:15px system-ui,sans-serif}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0}main{max-width:1560px;margin:auto;padding:42px 5vw 30px}header{display:flex;align-items:end;justify-content:space-between;gap:24px}.eyebrow{text-transform:uppercase;font-size:10px;letter-spacing:.24em;color:#89a5ad}h1{font:400 clamp(48px,7vw,90px) Georgia,serif;color:#ede4d2;margin:10px 0 5px}h1 em{color:#b8945b;font-weight:400}header p{max-width:360px;color:#91a2a8;font-size:13px;line-height:1.7;margin:0 0 10px}nav{display:flex;gap:8px;overflow-x:auto;margin:28px 0 18px;padding-bottom:4px}button,a{font:inherit}nav button{flex:none;text-align:left;background:#101c23;border:1px solid #26383f;border-radius:9px;padding:12px 20px;color:#92a8ae;cursor:pointer}nav button[aria-selected=true]{background:#26302c;border-color:#877449;color:#e3cc99}nav button small{display:block;color:#667e89;font-size:10px;margin-top:5px}.specimen{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(250px,.8fr);border:1px solid #25353c;border-radius:16px;overflow:hidden}.image-stage{background:#070c10;position:relative;min-height:520px;display:flex;align-items:center;justify-content:center}.image-stage img{width:100%;height:600px;object-fit:contain;cursor:zoom-in;display:block}.image-stage .empty{color:#839ca6;padding:80px 40px;text-align:center}.caption{position:absolute;left:20px;bottom:18px;padding:7px 11px;background:#080d12c9;color:#98adb4;font-size:10px;letter-spacing:.1em;border-radius:6px}.image-nav{position:absolute;right:20px;bottom:18px;display:flex;gap:7px;align-items:center}.image-nav button{background:#101d25e8;border:1px solid #455660;color:#ddd9c8;border-radius:7px;width:33px;height:30px;cursor:pointer}.image-nav output{font:10px ui-monospace,monospace;margin:0 5px;color:#a4b5bb}.info{background:#0e1820;padding:36px;display:flex;flex-direction:column}h2{font:400 38px Georgia,serif;color:#f0e3c8;margin:20px 0 8px}.subtitle{color:#b39862;font:16px Georgia,serif}.info p{line-height:1.8;font-size:13px;color:#9cb0b7}.facts{display:flex;gap:20px;flex-wrap:wrap;border-top:1px solid #243740;padding-top:22px;margin-top:10px}.facts div{font:10px ui-monospace,monospace;color:#6f8995}.facts strong{font-size:15px;font-weight:400;color:#becacc;display:block;margin-bottom:7px}.actions{margin-top:auto;padding-top:28px;display:flex;flex-direction:column;gap:14px}a{color:#b4c8ca;text-decoration:none}a:hover{text-decoration:underline}.primary{background:#c4aa73;color:#152027;border:0;border-radius:7px;padding:13px 18px;text-align:center;font-size:12px;font-weight:600;cursor:pointer}.links{display:flex;flex-wrap:wrap;gap:18px;font-size:11px}.strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-top:24px}.tile{background:#0d161c;padding:0;overflow:hidden;border:1px solid #26353b;border-radius:10px;cursor:pointer;color:#b8c3c4;text-align:left}.tile img{width:100%;height:145px;object-fit:cover;background:#080d12;display:block}.tile div{padding:13px 16px}.tile small{color:#6e8792;font-size:10px;display:block;margin-top:6px}.tile.active{border-color:#9c875c}.tail{margin-top:28px;padding-top:23px;border-top:1px solid #23323a;display:flex;justify-content:space-between;gap:20px;font-size:11px;color:#6c8793}.tail a{color:#8b9eab}dialog{max-width:95vw;width:1100px;background:#070c10;border:1px solid #526066;padding:10px;border-radius:12px;color:#c9d6d6}dialog::backdrop{background:#020608e8}dialog img{display:block;width:100%;max-height:80vh;object-fit:contain}dialog button{float:right;background:#24353c;border:0;color:#ddd;padding:8px 12px;border-radius:5px;cursor:pointer}dialog p{padding:0 12px;font-size:11px}@media(max-width:900px){.specimen{grid-template-columns:1.25fr 1fr}.info{padding:24px}.image-stage{min-height:460px}.image-stage img{height:500px}}@media(max-width:650px){main{padding:25px 18px}header{display:block}header p{max-width:100%;margin-top:15px}.specimen{display:block}.image-stage{min-height:340px}.image-stage img{height:360px}.info{padding:25px}.actions{padding-top:20px}.strip{grid-template-columns:1fr 1fr}.tile img{height:110px}.tail{display:block;line-height:2}nav button{padding:10px 14px}h2{margin-top:12px}}
</style></head><body><main><header><div><div class="eyebrow">Active matter / process collection</div><h1>Interior <em>/ studies</em></h1></div><p>A material can carry a pulse, keep a trace, and change what passes through it next. Explore the specimens from several angles.</p></header><nav id="nav" aria-label="Choose a specimen"></nav><section class="specimen"><div class="image-stage"><img id="hero" alt=""><div id="empty" class="empty" hidden>Open the volume to explore this recording.</div><div class="caption" id="caption"></div><div class="image-nav" id="image-nav"><button id="prev" aria-label="Previous image">←</button><output id="image-count"></output><button id="next" aria-label="Next image">→</button></div></div><div class="info"><div class="eyebrow" id="number"></div><h2 id="name"></h2><div class="subtitle" id="subtitle"></div><p id="description"></p><div class="facts" id="facts"></div><div class="actions"><a id="open" class="primary">Open interactive volume ↗</a><div class="links"><a id="notes" target="_blank">Process notes</a><a id="manifest" target="_blank">Recording data</a><a id="config" target="_blank">Parameters</a><button class="primary" id="expand" style="padding:0;background:none;color:#aebdbd;font-weight:400">Enlarge image ↗</button></div></div></div></section><div class="strip" id="strip"></div><div class="tail"><span id="summary"></span><span><a href="../docs/process-atlas.md">Process atlas</a> · <a href="../docs/rendering.md">Optical notes</a> · <a href="../docs/recording.md">Recordings</a></span></div></main><dialog id="lightbox"><button id="close">Close ×</button><img id="large" alt=""><p id="large-caption"></p></dialog><script id="specimens" type="application/json">__DATA__</script><script>
const specimens=JSON.parse(document.getElementById('specimens').textContent),$=id=>document.getElementById(id);let current=0,imageIndex=0;
function el(tag,text){let e=document.createElement(tag);if(text)e.textContent=text;return e;}
specimens.forEach((s,i)=>{let b=el('button',s.name);b.type='button';b.setAttribute('aria-selected','false');b.append(el('small',s.viewer?'Volume + rendered views':'Rendered views'));b.onclick=()=>select(i);$('nav').append(b);let tile=el('button');tile.className='tile';tile.setAttribute('aria-label','Select '+s.name);if(s.images.length){let img=el('img');img.src=s.images[0].src;img.loading='lazy';img.alt=s.name+' preview';tile.append(img);}let text=el('div',s.name);text.append(el('small',s.subtitle));tile.append(text);tile.onclick=()=>select(i);$('strip').append(tile);});
function showImage(){let s=specimens[current],im=s.images[imageIndex];$('hero').hidden=!im;$('empty').hidden=!!im;if(im){$('hero').src=im.src;$('hero').alt=s.name+' — '+im.caption;$('caption').textContent=im.caption;}else{$('hero').removeAttribute('src');$('caption').textContent='Recorded specimen';}$('image-nav').hidden=s.images.length<2;$('image-count').textContent=(imageIndex+1)+' / '+s.images.length;$('expand').hidden=!im;}
function select(i){current=i;imageIndex=0;let s=specimens[i];$('number').textContent='Specimen '+String(i+1).padStart(2,'0');for(let key of ['name','subtitle','description'])$(key).textContent=s[key];$('facts').replaceChildren();let facts=[];if(s.shape.length)facts.push([s.shape.join(' × '),'cells']);if(s.frames)facts.push([s.frames,'captured frames']);if(s.backend)facts.push([s.backend,'simulation']);for(let [value,label] of facts){let f=el('div');f.append(el('strong',String(value)),document.createTextNode(label));$('facts').append(f);}$('open').hidden=!s.viewer;if(s.viewer)$('open').href=s.viewer;$('notes').hidden=!s.notes;if(s.notes)$('notes').href=s.notes;$('manifest').href=s.manifest;$('config').hidden=!s.config;if(s.config)$('config').href=s.config;[...$('nav').children].forEach((b,j)=>b.setAttribute('aria-selected',j===i?'true':'false'));[...$('strip').children].forEach((b,j)=>b.classList.toggle('active',j===i));showImage();location.hash=s.id;}
function cycle(delta){let count=specimens[current].images.length;if(count){imageIndex=(imageIndex+delta+count)%count;showImage();}}
$('prev').onclick=()=>cycle(-1);$('next').onclick=()=>cycle(1);function expand(){let im=specimens[current].images[imageIndex];if(!im)return;$('large').src=im.src;$('large').alt=$('hero').alt;$('large-caption').textContent=$('hero').alt;$('lightbox').showModal();}$('hero').onclick=expand;$('expand').onclick=expand;$('close').onclick=()=>$('lightbox').close();$('lightbox').onclick=e=>{if(e.target===$('lightbox'))$('lightbox').close();};$('summary').textContent=specimens.length+' available specimens · local collection';let chosen=specimens.findIndex(s=>s.id===location.hash.slice(1));if(specimens.length)select(chosen<0?0:chosen);else{$('description').textContent='No specimen output is available yet.';}
</script></body></html>'''
(root/'index.html').write_text(html.replace('__DATA__',json.dumps(items,separators=(',',':')).replace('</','<\\/')));print(f'{root}/index.html: {len(items)} specimens')
